insert into public.control_register (id, title, type, description) values
  ('1baddb0f-8418-5ae3-9d0a-76a2f20feff0', 'Assessment shared and reviewed', 'Administrative', 'Staff are briefed on this assessment, sign to confirm, and it is reviewed yearly or after any incident or change.'),
  ('cba91fef-f21a-5b99-b184-75478b7f49bc', 'Induction and task training', 'Administrative', 'Everyone receives induction and task-specific training before starting, with records kept.'),
  ('4f46e170-468f-5199-b4c2-126fbac94cc6', 'Competent supervision', 'Administrative', 'Work is supervised by someone competent who can step in when standards slip.'),
  ('ffef01b3-656a-5b69-a06f-ddc92292b269', 'Report defects and near misses', 'Administrative', 'Staff know how to report hazards, defects and near misses, and reports are acted on promptly.'),
  ('ff96b26d-b1cd-5b93-ac78-95b6e0623865', 'First aid cover', 'Administrative', 'Trained first aiders and stocked first aid kits are available on every shift, with contact details displayed.'),
  ('b69095a4-db2c-50fe-9dfc-ac28f8c71329', 'Emergency procedure', 'Administrative', 'A written emergency procedure is in place, practised and known to all staff.'),
  ('612b911e-1fad-5246-acad-190a2c50c22d', 'Good housekeeping', 'Administrative', 'Work areas are kept tidy, with materials stored away and waste removed regularly.'),
  ('ff6aab53-b67a-5fdb-a124-62db2b83d339', 'Authorised and competent users only', 'Administrative', 'Only trained, authorised people may carry out this task or use this equipment.'),
  ('13d9af1c-715e-5172-9698-e1c6c810e968', 'Permit to work', 'Administrative', 'A permit to work controls the task, setting out isolation, precautions and sign-off.'),
  ('d1ca3a97-6442-5891-826e-c2e582ac9fbb', 'Safe system of work', 'Administrative', 'A written safe system of work or method statement is followed for the task.'),
  ('9fa1706c-85c4-5484-928b-e57c276179ea', 'Health surveillance', 'Administrative', 'Health surveillance is provided where required, and results are acted on.'),
  ('4b9406b2-64c6-5ac8-a012-f4e3bcb7f5dd', 'Occupational health referral', 'Administrative', 'Staff can be referred to occupational health, and reasonable adjustments are made.'),
  ('11d57bc7-4210-5004-b10c-659e5ffa4e22', 'Pre-use checks', 'Administrative', 'Equipment is visually checked before each use; faulty items are labelled and taken out of use.'),
  ('4def2546-740c-5cee-8dd6-c6dd289fb3f8', 'Planned maintenance', 'Administrative', 'Equipment is maintained to the manufacturer''s schedule by a competent person, with records kept.'),
  ('d9ff980f-5b7e-50cd-86a0-10b621a8b9eb', 'Statutory inspection', 'Administrative', 'Thorough examinations required by law (e.g. LOLER, PSSR) are carried out at the right intervals.'),
  ('65c771bd-fe9d-56df-952d-afc5014866a7', 'Structures inspected and within load limits', 'Administrative', 'Structures are built to the design or supplier instructions, kept within their safe working load and inspected by a competent person.'),
  ('bfd408f2-7f71-5ddd-b108-a79bd68ce048', 'Safety signs and barriers', 'Engineering', 'Hazard areas are signed and, where needed, barriered off to keep others away.'),
  ('d2a4999f-9156-5c50-9928-0e714dc25b65', 'Adequate lighting', 'Engineering', 'Work areas, stairs and routes are well lit, and failed lights are replaced promptly.'),
  ('c2b14625-d252-58a5-b745-4822af7af914', 'Welfare facilities', 'Administrative', 'Toilets, washing facilities, drinking water and rest areas are provided and kept clean.'),
  ('55f2e8ca-df60-512d-a723-0ff73dfbd8c7', 'Young worker assessment', 'Administrative', 'Workers under 18 have a specific assessment and are kept away from prohibited tasks.'),
  ('5d5d7c91-1e44-52f1-85f7-cd95b7b5492f', 'New and expectant mothers assessment', 'Administrative', 'An individual assessment is completed when an employee tells us she is pregnant or breastfeeding.'),
  ('eaf9fc2e-dde7-5593-b014-f6caab44f694', 'Contractor vetting', 'Administrative', 'Contractors are checked for competence and insurance, and their assessments and method statements are reviewed.'),
  ('95e9522b-b5de-58ef-8a52-5245126cba47', 'Contractor sign-in and induction', 'Administrative', 'Contractors sign in, receive a site induction and are told about site hazards and emergency arrangements.'),
  ('b4112a18-b41c-5d2d-88d1-fdac81dcb66d', 'Spills cleaned immediately', 'Administrative', 'Spills are cleaned straight away using the right equipment, with wet floor signs in place.'),
  ('92a0472c-311e-5811-b625-82e881aa786b', 'Floors kept in good repair', 'Engineering', 'Damaged flooring, mats and edges are repaired or replaced promptly.'),
  ('d402697a-5e44-5e38-9a51-3cf757ad07ab', 'Cables managed', 'Engineering', 'Trailing cables are avoided, routed safely or covered with cable protectors.'),
  ('8a8815b1-4316-532d-a99b-751a076f7e7b', 'Slip-resistant footwear', 'PPE', 'Suitable slip-resistant footwear is worn in wet or greasy areas.'),
  ('90522c78-0d30-5705-a9e2-971674a2e9d2', 'Clear walkways', 'Administrative', 'Walkways, stairs and exits are kept free of obstructions.'),
  ('bdf531ac-6a2b-5a18-bde5-38e1d5b77117', 'Handrails on stairs', 'Engineering', 'Stairs and steps have secure handrails and highlighted nosings.'),
  ('e3922ae5-5732-5ea6-8731-347140bfa9cc', 'Entrance matting', 'Engineering', 'Entrance matting stops water being walked in during wet weather.'),
  ('a92c5ad8-ab65-53bf-9850-837294178d1d', 'Gritting and snow clearance', 'Administrative', 'Priority routes are gritted and cleared before people arrive in icy weather.'),
  ('b9d1b184-2346-50ed-b32b-ab92aa43c413', 'Avoid work at height', 'Elimination', 'Work is done from the ground where possible, for example using extension poles.'),
  ('5a5a2b07-8d29-5b14-b37f-e5183796476f', 'Ladders for short, light work only', 'Administrative', 'Ladders are used only for short-duration, light work where a safer platform is not justified.'),
  ('8c71d1ac-ba5c-59e3-8109-f79ff5c7b649', 'Ladder inspections', 'Administrative', 'Ladders are pre-use checked and formally inspected, with a register kept.'),
  ('8e1ef687-b355-5094-8b6f-7ba980ba6c15', 'Safe ladder use', 'Administrative', 'Ladders are set on firm, level ground, secured or footed, and users keep three points of contact.'),
  ('ce6967d0-de38-54c5-b513-438867bca076', 'Podium steps or platforms', 'Substitution', 'Podium steps or work platforms with guard rails are used instead of ladders where possible.'),
  ('d6bf64f7-afd9-5aed-a175-4abbadd53039', 'Towers erected by trained people', 'Administrative', 'Mobile towers are erected and inspected by trained people, with outriggers and brakes in use.'),
  ('341a167e-0d76-5094-b7df-eb74723e0863', 'Edge protection', 'Engineering', 'Guard rails and toe boards are in place at open edges, openings and roof perimeters.'),
  ('5ad6aafa-d26f-5c6a-a2ff-ad21ffaeb783', 'Fragile surfaces protected', 'Engineering', 'Fragile roofs and rooflights are covered or protected, and staging is used to spread the load.'),
  ('5a610c2d-af81-590a-ba30-76851588d304', 'Fall arrest or restraint', 'PPE', 'A harness and lanyard attached to a suitable anchor is used where collective protection is not possible.'),
  ('6134a8ee-d1e3-5dc9-a8c1-1921001d1d80', 'Trained MEWP operators', 'Administrative', 'MEWPs are operated by trained, authorised operators, with ground conditions checked and a rescue plan.'),
  ('b77a87de-3c61-5a0e-bdfd-de01ecc96738', 'Exclusion zone below', 'Engineering', 'The area below work at height is barriered to protect people from falling objects.'),
  ('27db63c9-6076-5b3e-bcf6-9cc48761d726', 'Rescue plan', 'Administrative', 'A rescue plan is in place and practised before work at height or in confined spaces starts.'),
  ('65c28cd5-70da-5cb5-a4e0-bae94b1a0684', 'Tools and materials secured', 'Engineering', 'Tools are tethered and materials secured so they cannot fall.'),
  ('cb4460d2-a878-5b24-9a51-d131db91f4f0', 'Stop work in bad weather', 'Administrative', 'Work stops in high winds, heavy rain, ice or lightning.'),
  ('eb354004-21bf-5ba1-bb8b-ba937fd35154', 'Manual handling assessment', 'Administrative', 'Significant lifting tasks are assessed, considering the task, load, environment and individual.'),
  ('2f998928-bfb8-5434-8a1f-66ed0f54b7fe', 'Handling aids', 'Substitution', 'Trolleys, sack trucks, hoists or lifting aids are provided and used.'),
  ('e9746ff0-0a94-5e44-9a9e-193586f269e8', 'Manual handling training', 'Administrative', 'Staff are trained in good handling technique with refresher training.'),
  ('d437ccc2-71bb-58c4-ab71-c1452e9f1d4b', 'Loads broken down', 'Administrative', 'Loads are split into smaller, lighter units or ordered in smaller pack sizes.'),
  ('eb4b1b96-476e-5607-a280-3d94c98942d4', 'Team lifting', 'Administrative', 'Two or more people lift heavy or awkward items, with one person giving instructions.'),
  ('3587e3d6-2675-51f6-be17-8a7d0de2db8a', 'Heavy items at waist height', 'Engineering', 'Storage is arranged so heavy and frequently used items sit between knee and shoulder height.'),
  ('28d93492-2f4a-5575-819c-d6ba530310df', 'Task rotation and breaks', 'Administrative', 'Repetitive tasks are rotated and regular breaks are taken.'),
  ('b715b9f6-30b6-5e8c-9f82-9cea6f45abc3', 'Individual moving and handling plan', 'Administrative', 'Each person has a moving and handling plan, reviewed when their needs change.'),
  ('c5286bef-88a9-5015-8e68-c7a72599cb33', 'Hoists and slings', 'Engineering', 'Suitable hoists and correctly sized slings are used, with two carers where the plan requires.'),
  ('006b5bc4-9827-5784-aa46-da71d17fa04b', 'Hoist examination', 'Administrative', 'Hoists and slings are thoroughly examined every six months and checked before use.'),
  ('02386e97-94b3-5428-9fae-3b5b426cbefb', 'Height-adjustable beds and baths', 'Engineering', 'Height-adjustable beds and baths are used to avoid bending and stooping.'),
  ('7fd2d180-d89d-575f-b120-090a87bdbb18', 'Fixed wiring inspected', 'Administrative', 'The fixed electrical installation is inspected and tested by a qualified electrician at recommended intervals.'),
  ('aed416fb-364e-5953-9c5d-7b8f952aabfd', 'Portable appliance checks', 'Administrative', 'Portable equipment is inspected and tested at intervals suited to its use.'),
  ('e3488a53-4a62-56c1-9e46-74957b630512', 'Visual checks of leads and plugs', 'Administrative', 'Users check plugs, leads and casings before use and report damage.'),
  ('76c270f8-a3b0-53e6-b7e9-a55ba515af81', 'RCD protection', 'Engineering', 'Residual current devices protect portable equipment, especially outdoors.'),
  ('5587974d-29c7-5610-b462-fcd20c3b9d44', 'No live working', 'Elimination', 'Equipment is isolated and proved dead before work; live working is not permitted.'),
  ('f5e0bf24-9326-5238-b9c8-9ffe313e7a44', 'Lock-off and isolation', 'Engineering', 'Isolation points are locked off and tagged during maintenance or cleaning.'),
  ('3d9bdb39-745e-5122-87e7-793f97919e23', 'Qualified electricians only', 'Administrative', 'Electrical installation and repair is carried out only by qualified electricians.'),
  ('184df3c2-b8e4-56f6-86b9-4a3e3072ea9a', 'Services located before digging or drilling', 'Administrative', 'Underground and hidden services are located with drawings and a cable detector before breaking ground or drilling.'),
  ('d4e00cdb-cc95-5154-93e5-639790bf7b97', '110V or battery tools', 'Substitution', '110V reduced-voltage or battery-powered tools are used on site.'),
  ('e324c8bf-0bc7-5256-97db-db15071d880b', 'Overhead line precautions', 'Administrative', 'Work near overhead power lines is planned with goal posts, barriers or a safe clearance distance.'),
  ('8f962b94-e359-56bc-9d18-bbf3e9bddf7b', 'Fire risk assessment', 'Administrative', 'A fire risk assessment is in place and reviewed by a competent person.'),
  ('1016be9e-3fc4-5d5c-8e83-1433e6100159', 'Fire detection and alarm', 'Engineering', 'Fire alarms are tested weekly and serviced by a competent engineer.'),
  ('a2822e33-1751-561b-9638-98a0c965013a', 'Fire extinguishers', 'Engineering', 'Suitable extinguishers are provided, checked monthly and serviced annually.'),
  ('9923ad6e-60ba-5983-9757-33f49fc8d32c', 'Escape routes kept clear', 'Administrative', 'Escape routes and fire exits are kept clear, signed and lit, with emergency lighting tested.'),
  ('1a534f79-8e9d-5d0d-a075-e3088710ff87', 'Fire drills', 'Administrative', 'Fire drills are held at least twice a year and fire marshals are trained.'),
  ('da5eb84d-1147-5c06-aa67-0252ada9c647', 'Personal evacuation plans', 'Administrative', 'Anyone who needs help to evacuate has a personal emergency evacuation plan.'),
  ('8b3012a0-64cc-5f2a-86a1-8e4159c319b7', 'Ignition sources controlled', 'Administrative', 'Smoking is restricted to designated areas and heaters and hot equipment are kept clear of combustibles.'),
  ('78c7fda3-b0be-59be-959a-402ced32e25e', 'Combustible storage controlled', 'Administrative', 'Combustible materials and waste are kept to a minimum and stored away from ignition sources.'),
  ('e3efb315-814c-5bf8-bc13-5f4e84e7be3c', 'Hot work permit', 'Administrative', 'Hot work needs a permit, a fire watch during work and a check of the area afterwards.'),
  ('e35ab564-1d44-5e0d-992a-f9869df77e02', 'Flammables store', 'Engineering', 'Flammable liquids and gases are kept in minimum quantities in a ventilated, signed store or cabinet.'),
  ('78840186-c2b9-5e8f-a585-65d293c58340', 'Fire doors maintained', 'Engineering', 'Fire doors are kept shut, self-closing and in good repair.'),
  ('357e85c1-5802-5a5c-ba2a-61a47f82740d', 'COSHH assessments', 'Administrative', 'Each hazardous substance has a COSHH assessment, and safety data sheets are available.'),
  ('43dd061b-ee5c-55a5-8aec-ae1e1402dd2d', 'Safer products chosen', 'Substitution', 'Less hazardous products, forms (e.g. pellets instead of powders) or methods are chosen where possible.'),
  ('6ce71085-fd3d-5bb3-8cb8-5d6cc0bcdfb5', 'Secure, labelled storage', 'Engineering', 'Substances are stored securely in original labelled containers, away from food and incompatible chemicals.'),
  ('3152c559-a147-5ddc-b4b5-e10a32450a37', 'Local exhaust ventilation', 'Engineering', 'Dust and fume are captured at source by LEV, which is examined every 14 months.'),
  ('dc916be0-17d6-567a-9852-9351fe05e6d0', 'Gloves', 'PPE', 'Suitable gloves for the substance or task are provided and worn.'),
  ('05a8b016-b9ca-5982-82d6-533680c043ec', 'Eye protection', 'PPE', 'Safety glasses, goggles or a face shield are worn where there is a risk to the eyes.'),
  ('c0e990ae-0aa6-51ed-8b18-301cb083995c', 'Face-fit tested RPE', 'PPE', 'Suitable respiratory protection is provided, face-fit tested and worn.'),
  ('145c158f-f363-5e23-a2ec-0ed8ed16e5c8', 'Eyewash and washing facilities', 'Engineering', 'Eyewash and hand washing facilities are available near where substances are used.'),
  ('7915e10b-f5aa-5458-ae76-b6290599adee', 'Dosing and dilution systems', 'Engineering', 'Chemicals are dispensed through dosing systems or measured correctly; mixing products is not allowed.'),
  ('e8a2c33e-3b46-5344-aa78-8bc3885d62d3', 'Skin care and checks', 'Administrative', 'Staff dry hands thoroughly, use moisturiser, and report skin problems early.'),
  ('b67ca73c-9cba-51d0-9f78-ed37e49ff05c', 'Water suppression or on-tool extraction', 'Engineering', 'Cutting and drilling uses water suppression or on-tool extraction to control dust.'),
  ('40118497-689e-5fe5-aa42-25ac1171bbff', 'Asbestos register checked', 'Administrative', 'The asbestos register is checked before any work that could disturb the building fabric.'),
  ('ab5c1276-14c7-5ec2-a234-2bf2de7fd42e', 'Refurbishment survey', 'Administrative', 'A refurbishment and demolition survey is done before intrusive work.'),
  ('59e4ed4d-85cc-53b6-aa7f-a1cd3d80cf0b', 'Asbestos awareness training', 'Administrative', 'Staff who could disturb asbestos have asbestos awareness training.'),
  ('77545f84-310b-5bbf-8113-c9d9a65443fa', 'Stop if suspect material found', 'Administrative', 'Work stops immediately if suspected asbestos is found, and the area is closed off.'),
  ('a37d9ac6-4bc0-5350-a31a-337636af3949', 'Licensed contractors', 'Administrative', 'Licensable asbestos work is carried out only by a licensed contractor.'),
  ('86b95475-ad37-5ac5-83c0-c17c9f1c69a5', 'Legionella risk assessment', 'Administrative', 'A legionella risk assessment is in place and a responsible person is appointed.'),
  ('bb328a72-8a79-51ec-b10c-68f1dd897622', 'Water temperatures monitored', 'Administrative', 'Hot water is stored at 60°C or above and cold water kept below 20°C, with monthly checks.'),
  ('041ef93f-b0e5-53c7-888e-d1475e5134c1', 'Little-used outlets flushed', 'Administrative', 'Little-used outlets are flushed weekly and showerheads cleaned and descaled quarterly.'),
  ('6c782933-da23-5c8c-bcb5-f612bb419a2d', 'Thermostatic mixing valves', 'Engineering', 'TMVs limit outlet temperatures where scalding is a risk and are serviced regularly.'),
  ('4ea898a8-6467-59e1-9918-098ed84f2cd2', 'Noise assessment', 'Administrative', 'Noise levels are measured and exposure assessed by a competent person.'),
  ('d8b0e02c-31d1-5dba-b0e3-8a11d0125d1f', 'Quieter equipment', 'Substitution', 'Quieter machines and methods are chosen, and equipment is maintained to stay quiet.'),
  ('44272122-a15a-5324-8124-a0066290e05f', 'Hearing protection zones', 'Engineering', 'Areas above the upper action value are marked as hearing protection zones.'),
  ('2b3597b8-e499-51ae-bd1c-f5ffe0fd029e', 'Hearing protection', 'PPE', 'Suitable hearing protection is provided and worn where required.'),
  ('c4e26af5-3cb2-57df-af67-e930e5b841de', 'Low-vibration tools', 'Substitution', 'Low-vibration tools are chosen and kept sharp and well maintained.'),
  ('838b915f-5647-5282-8be9-0858dfe1dcd4', 'Trigger time limits', 'Administrative', 'Trigger times are recorded and kept within exposure limits.'),
  ('88fc5aac-74c1-5f2b-9375-0cc2293606bf', 'Fixed and interlocked guards', 'Engineering', 'Dangerous parts are enclosed by fixed or interlocked guards that are checked before use.'),
  ('dd0c3db3-def0-5bb1-9431-b68b0e336d26', 'Emergency stops', 'Engineering', 'Emergency stops are within reach and tested regularly.'),
  ('7c209a12-8a4c-548f-8604-17a298fa7778', 'No loose clothing or jewellery', 'Administrative', 'Loose clothing, jewellery and long hair are secured near rotating parts.'),
  ('f7c20d8f-5d11-50e2-8083-ab923e364490', 'Machine-specific training', 'Administrative', 'Operators are trained and signed off on each machine before using it unsupervised.'),
  ('68a7834d-dc71-5539-a901-06fcd9c2c641', 'Push sticks and jigs', 'Engineering', 'Push sticks, jigs and holders keep hands away from blades and cutters.'),
  ('1f5aa086-5eac-5f68-8d45-4b56e1bc3af2', 'Blades and cutters maintained', 'Administrative', 'Blades and cutters are sharp, correctly fitted and changed by competent people.'),
  ('f3591e45-b323-5bce-8722-fc99ecf75d5a', 'Abrasive wheels mounted by trained people', 'Administrative', 'Abrasive wheels are mounted only by trained people and run within their speed rating.'),
  ('e80be16a-5b6c-5f7c-929a-44fb0b7e726d', 'Two-hand and light guard controls', 'Engineering', 'Two-hand controls, light curtains or interlocks protect operators on presses and guillotines.'),
  ('a8df64d3-d186-5487-bc75-f61d8c23a4db', 'Press and guard inspections', 'Administrative', 'Power presses and their guards are inspected after setting and thoroughly examined by law.'),
  ('8b7010fb-aa74-54dd-a37b-78f592b12da1', 'Pedestrians and vehicles kept apart', 'Engineering', 'Pedestrian routes are separated from vehicle routes with barriers and marked crossings.'),
  ('9a283c31-45ec-5c19-856f-c4bcc0a73a00', 'Site speed limit', 'Administrative', 'A site speed limit is signed and enforced.'),
  ('93c3a4e5-b68f-5da3-bdd1-83f1773af9f2', 'Trained banksman for reversing', 'Administrative', 'Reversing is avoided where possible; where needed, a trained banksman guides the vehicle.'),
  ('8998be1a-75f1-5856-b401-1b7c247de30d', 'High-visibility clothing', 'PPE', 'High-visibility clothing is worn in yards and around vehicles.'),
  ('0c937124-0542-5211-8650-629d4708aa6a', 'Trained and authorised drivers', 'Administrative', 'Lift truck and plant drivers are trained, assessed and authorised in writing.'),
  ('95a0103b-28a9-5ee1-a7a6-b79cab450ad3', 'Daily vehicle checks', 'Administrative', 'Drivers complete daily checks and defects are reported before use.'),
  ('9b3ef449-0f30-5ff3-8956-154db76c40e6', 'Key control', 'Administrative', 'Keys are removed when vehicles and plant are left, so only authorised drivers can use them.'),
  ('7b8e04a1-02ee-5842-b5e5-0cb56365f55a', 'Reversing aids', 'Engineering', 'Vehicles have cameras, sensors, alarms and mirrors in working order.'),
  ('c5150e01-3288-539f-a45e-a95fa5ba7f6d', 'Loads secured', 'Administrative', 'Loads are restrained to industry guidance, checked before departure and after partial unloading.'),
  ('027dde3e-9df7-535b-bfc8-28b38ef34fc1', 'Vehicles immobilised', 'Engineering', 'Vehicles are braked, switched off and chocked or locked out during loading and maintenance.'),
  ('efb64ca1-8032-5314-94c7-36a269d33ed4', 'Licence checks', 'Administrative', 'Driving licences are checked on recruitment and at least yearly.'),
  ('4c88975b-83c1-5d33-b4a4-aa18681d22fb', 'Vehicles serviced and checked', 'Administrative', 'Vehicles are serviced to schedule, with walk-round checks before journeys.'),
  ('41b9fdcb-a9ab-5086-927b-cf65c1226d00', 'Journey planning', 'Administrative', 'Journeys are planned with breaks every two hours and overnight stays where needed.'),
  ('c7fbdc71-454c-53ea-97d5-093e0f5dd81e', 'No handheld phones', 'Administrative', 'Handheld phones are not used while driving; calls wait until parked safely.'),
  ('89f46227-2452-586e-b4b0-8c92a7455eb9', 'Fatigue managed', 'Administrative', 'Working hours and shift patterns limit fatigue, and staff must not drive when tired.'),
  ('05d62745-4808-5952-a8a6-b907b390b7c2', 'Breakdown cover and procedure', 'Administrative', 'Vehicles have breakdown cover and drivers know what to do if they break down.'),
  ('86ff605d-eb2f-5b05-a1d0-70ffd8147ab3', 'Lone working procedure', 'Administrative', 'A lone working procedure sets out what lone workers may and may not do.'),
  ('e3730c91-1873-5a16-8026-502f8b7f54ef', 'Check-in system', 'Administrative', 'Lone workers check in at agreed times, with an escalation plan if they do not.'),
  ('0064efe9-7778-562d-b1bf-23a507163dad', 'Lone worker device or app', 'Engineering', 'Lone workers carry a charged phone or lone worker device with an alert function.'),
  ('591d637a-e6d4-5e3f-9da6-7d303f65bae3', 'High-risk tasks not done alone', 'Elimination', 'High-risk tasks are not carried out by someone working alone.'),
  ('95e61ca1-1138-5774-b790-9b66cc5e4924', 'Conflict resolution training', 'Administrative', 'Staff are trained to recognise and defuse conflict and to leave if threatened.'),
  ('56029039-28e9-5b23-8e8b-7b6f2b047ac3', 'Incidents recorded and reviewed', 'Administrative', 'Abuse and violent incidents are recorded, reviewed and supported.'),
  ('21639d17-4840-5dea-a6e3-b8f05b8fce7f', 'Secure layout and alarms', 'Engineering', 'Counters, screens, CCTV and panic alarms protect staff where needed.'),
  ('b278b642-643e-5f6b-bffe-093f28df5a24', 'Cash kept to a minimum', 'Administrative', 'Cash in tills is kept low and banked at varied times, never alone.'),
  ('8f5422fb-f2ff-5d0a-9d1d-fa66ed5b94c2', 'Stress risk assessment', 'Administrative', 'Stress risks are assessed against the HSE Management Standards.'),
  ('d5a15d7c-6762-5f0b-a822-35e60d4d55eb', 'Regular one-to-ones', 'Administrative', 'Managers hold regular one-to-ones and monitor workload and hours.'),
  ('18e66f33-b69e-5e91-b86a-52ec63fd562b', 'Employee assistance', 'Administrative', 'Staff can use an employee assistance programme or mental health first aiders.'),
  ('7617f173-10ba-57db-afa0-a73650531b94', 'Workstation assessments', 'Administrative', 'Display screen users complete workstation assessments and adjustments are made.'),
  ('267ac3bb-6092-50ea-b485-b7f3b9950b70', 'Adjustable chairs and screens', 'Engineering', 'Adjustable chairs, screen risers and other equipment are provided as needed.'),
  ('d7d79355-5133-5a04-9cfc-df225519cf34', 'Eye tests', 'Administrative', 'Display screen users are offered eye tests and glasses for screen use when needed.'),
  ('65a4f71a-0527-55ba-b798-241c26f045ad', 'Home working assessment', 'Administrative', 'Home workers complete a home workstation and environment check.'),
  ('e68dbd03-d662-564a-bc73-79d28242f90f', 'Hand hygiene', 'Administrative', 'Hands are washed or sanitised before and after care, food handling and glove use.'),
  ('121008b4-9a92-562f-b45e-4be17cfdef03', 'Gloves and aprons', 'PPE', 'Disposable gloves and aprons are worn for contact with body fluids and changed between tasks.'),
  ('f4828674-9865-5cce-8d67-1d19521724d6', 'Clinical waste segregated', 'Administrative', 'Clinical and offensive waste is segregated, stored securely and collected by a licensed carrier.'),
  ('8fcaa051-749d-58fe-bb47-fa76d5a91c99', 'Sharps bins at point of use', 'Engineering', 'Sharps go straight into a sharps bin at the point of use, which is closed when three-quarters full.'),
  ('71972421-50c9-5c41-b370-e06e1bb1c1aa', 'Safer sharps', 'Substitution', 'Safety-engineered needles and devices are used where practicable; needles are never re-sheathed.'),
  ('3f1e53a4-9267-5c19-a4b0-ce290cbca288', 'Needlestick procedure', 'Administrative', 'A needlestick and splash procedure is displayed and staff know to seek urgent advice.'),
  ('4c6a79b3-db84-5f6e-a0fe-79af3102f5b5', 'Hepatitis B vaccination', 'Administrative', 'Staff at risk are offered hepatitis B vaccination.'),
  ('ea6191e4-423e-5819-92d2-54a8ff51c834', 'Cleaning schedule', 'Administrative', 'A cleaning schedule covers all areas and is signed off when complete.'),
  ('cd4eab5f-f71b-5c61-bac1-6e5c98cd08bc', 'Outbreak management', 'Administrative', 'Infection outbreaks are managed with isolation, enhanced cleaning and public health advice.'),
  ('92ac6049-8072-5f51-941b-ec70950f2973', 'Seasonal vaccination encouraged', 'Administrative', 'Staff are encouraged to have flu and other seasonal vaccinations.'),
  ('627b1c92-dbba-528a-af4f-ca86b359c844', 'Food safety management system', 'Administrative', 'A food safety management system based on HACCP is followed and records kept.'),
  ('b75f8e42-5a75-55b6-92b7-9da3c63afa67', 'Food hygiene training', 'Administrative', 'Food handlers hold food hygiene training suited to their role.'),
  ('68cfcb97-e4b0-51e0-aae7-0322816f6cbb', 'Allergen information', 'Administrative', 'Allergens are recorded for every dish, and staff check with the kitchen before answering customers.'),
  ('bab9aa2b-4b4c-5cd1-9313-be33ecd1eb3d', 'Allergen controls in preparation', 'Engineering', 'Separate equipment, areas or cleaning stops cross-contamination for allergen-free orders.'),
  ('98c1e2cc-1284-5d81-8ae8-8a5ac5de40cf', 'Temperatures monitored', 'Administrative', 'Fridge, freezer, cooking and hot-holding temperatures are checked and recorded.'),
  ('5b636f8f-e1a0-5b55-9c03-8a596bf020dd', 'Safe knife use', 'Administrative', 'Knives are sharp, the right size for the task, carried point down and stored in racks.'),
  ('739d9af4-001e-5b4e-8ecb-f3b810c5735c', 'Cut-resistant gloves', 'PPE', 'Cut-resistant gloves are worn for boning, slicing or cleaning blades.'),
  ('a2c3bf65-1375-5979-bc1a-8c9d3a2d8967', 'Thermostatically controlled fryers', 'Engineering', 'Fryers have thermostats and cut-outs; oil is changed cold or with a filter system.'),
  ('76b867be-6b51-5fb5-9680-b74e0bdff798', 'Hot surfaces and liquids', 'Administrative', 'Oven gloves are used, pan handles turned in, and hot liquids carried with care.'),
  ('6d0a0ea1-18e5-554b-b427-5d68d1acbd1a', 'Gas Safe servicing', 'Administrative', 'Gas appliances are installed and serviced by a Gas Safe registered engineer.'),
  ('a488d8e2-1191-5bdb-8bb0-6b5f4030bf18', 'Gas interlock and ventilation', 'Engineering', 'Commercial kitchen gas supplies are interlocked with the extraction system.'),
  ('9290ab86-4820-5271-bdec-b73c08cdae2e', 'Extraction cleaned', 'Administrative', 'Canopies, filters and ductwork are cleaned regularly to prevent fat build-up.'),
  ('eb0d96ab-df83-58cb-9698-5756d35fe424', 'Pool safety operating procedure', 'Administrative', 'A pool safety operating procedure covers normal operation and emergencies.'),
  ('2b13094b-4bd9-5d20-9116-b9d1f3cc36a2', 'Qualified lifeguards', 'Administrative', 'Qualified lifeguards supervise the pool in line with the assessed numbers.'),
  ('fa1a72b3-6005-5c61-b06e-a5add2ade7c3', 'Pool chemicals managed', 'Administrative', 'Pool chemicals are handled by trained staff, stored apart and dosed automatically.'),
  ('d8e42448-3377-501e-bbad-7f235a6331f7', 'Water quality tested', 'Administrative', 'Pool and spa water is tested several times a day and records kept.'),
  ('26acafd4-667a-5c42-9caf-93b98f1cd462', 'Depth markings and signs', 'Engineering', 'Water depths and pool rules are clearly displayed.'),
  ('3be24a9b-e5d8-52b4-bb77-6227fa49c9d8', 'Rescue equipment', 'Engineering', 'Throw lines, poles or buoyancy aids are available near water.'),
  ('af3b0f7d-fdf6-5934-9c00-e505ef257e7b', 'Animal handling procedure', 'Administrative', 'Animals are handled by experienced staff using suitable restraint and handling facilities.'),
  ('f71d2b9c-70ab-554a-961b-007893b2b178', 'Zoonoses precautions', 'Administrative', 'Staff wash hands, cover cuts and wear protective clothing to prevent infections from animals.'),
  ('f1c964c7-4d3f-5cee-920e-6054ed371817', 'Protective clothing for animals', 'PPE', 'Gauntlets, overalls and boots are worn where there is a risk of bites, kicks or scratches.'),
  ('e32c83f1-d301-57d7-a5a0-2fa83f6a7357', 'Pens and races in good repair', 'Engineering', 'Pens, gates, races and crushes are kept in good repair and used for handling.'),
  ('9eb34b6a-40ef-58ec-b229-f5b578d12ff5', 'Sun and weather protection', 'Administrative', 'Staff working outside have sun protection, water and suitable clothing for the weather.'),
  ('d60a4068-357d-5de5-8d08-cd490488b6ce', 'Leptospirosis precautions', 'Administrative', 'Staff cover cuts, wear gloves near water and rats, and carry a warning card.'),
  ('8b5f1674-734c-5c46-80dc-3b7ff9d42ac6', 'Certified pesticide users', 'Administrative', 'Pesticides are applied only by certified users following the label and a spray record.'),
  ('31c1842a-c34f-5a45-97f1-5bd865b601a4', 'Chainsaw certification', 'Administrative', 'Chainsaws are used only by certificated operators wearing full chainsaw protection.'),
  ('75ae9bbc-3040-5449-aef7-985695e86101', 'Chainsaw protective clothing', 'PPE', 'Chainsaw boots, trousers, gloves, helmet, visor and ear defenders are worn.'),
  ('19d1b454-239b-5103-ad9f-82f5dd424717', 'Debris guards and exclusion zones', 'Engineering', 'Mowers and strimmers have guards fitted, and others are kept a safe distance away.'),
  ('711731f1-0de3-5486-9a6b-7ca07edd98d7', 'Avoid entry', 'Elimination', 'Confined spaces are not entered unless the work cannot be done from outside.'),
  ('642cdea8-2f14-561c-8434-28d637ab4e40', 'Atmosphere monitoring', 'Engineering', 'The atmosphere is tested before and during entry with a calibrated gas detector.'),
  ('418f8792-b596-50f5-aa67-513db7666f3e', 'Cylinders stored safely', 'Engineering', 'Gas cylinders are stored upright, chained, outdoors or in a ventilated store, with valves protected.'),
  ('64dec7d3-85f9-5aca-b5c1-c7ff8b46215e', 'Cylinder trolleys', 'Engineering', 'Cylinders are moved on purpose-made trolleys, never rolled or dropped.'),
  ('32188dd7-b381-5cd6-8a9a-85f685f4f51e', 'Flashback arrestors', 'Engineering', 'Oxy-fuel sets have flashback arrestors and hoses in good condition.'),
  ('28d14538-d5d0-52fa-893e-cd150913c340', 'Written scheme of examination', 'Administrative', 'Pressure systems have a written scheme of examination and are examined by a competent person.'),
  ('39c8901b-197e-54d8-83b9-39517755b94f', 'Gas detection', 'Engineering', 'Gas detectors with alarms monitor areas where gases could build up.'),
  ('fc0619e4-49ec-54bc-9038-66880643b260', 'Construction phase plan', 'Administrative', 'A construction phase plan is in place and site rules are explained at induction.'),
  ('7ccab211-d81e-531c-847d-e999e36e13db', 'Site secured', 'Engineering', 'The site is fenced and secured to keep out the public, especially children.'),
  ('8c17b671-876b-58ba-a0c5-2934443ecb3c', 'Excavations supported', 'Engineering', 'Excavations are battered back or supported, inspected daily and protected with barriers.'),
  ('0ec50495-3612-5c5c-b56d-e236cd5c76df', 'Competent plant operators', 'Administrative', 'Plant is operated only by trained, certificated operators.'),
  ('fa024446-2882-54b9-96e3-598df81eeded', 'Scaffold inspections', 'Administrative', 'Scaffolds are erected by competent scaffolders and inspected every seven days and after bad weather.'),
  ('959da293-d7d3-5b9b-a247-0b1bdfb1a5a0', 'Site PPE', 'PPE', 'Hard hats, safety boots, hi-vis and gloves are worn on site.'),
  ('17adf3c8-37a3-5b4d-b4b6-68b6352a859f', 'Traffic management plan', 'Administrative', 'A traffic management plan controls deliveries, plant and pedestrians on site.'),
  ('32f856e1-dd5f-5c90-a4d7-8fbe97906c9f', 'Silica dust controlled', 'Engineering', 'Cutting stone, brick and concrete uses water suppression or extraction plus RPE.'),
  ('36d8dd6b-6ed2-5b12-929c-9bf32ae6077b', 'Public areas checked', 'Administrative', 'Customer areas are checked through the day for hazards and cleaned as needed.'),
  ('b82cb605-9efd-5e1f-9e0f-633ea21d003e', 'Safety glass and manifestation', 'Engineering', 'Glazing at low level is safety glass and large glass panels have visible markings.'),
  ('194109ee-aabf-5387-a51a-4810c67401b6', 'Window restrictors', 'Engineering', 'Windows that vulnerable people can reach are fitted with tamper-proof restrictors.'),
  ('f90ed736-041b-5f91-a13c-91b6c0798292', 'Lifts maintained and examined', 'Administrative', 'Passenger and goods lifts are maintained and thoroughly examined every six months.'),
  ('dea04399-65a0-56c8-9a70-8c93b26fd9ec', 'Racking inspected', 'Administrative', 'Racking is installed to load limits, signed with capacities and inspected by a competent person.'),
  ('d8681316-cb5c-5fe5-9091-bc8a53443c57', 'Delivery procedure', 'Administrative', 'Deliveries follow an agreed procedure, with drivers directed to a safe area.'),
  ('cd9953b7-c436-502f-b7f0-9492854156ef', 'Care plans', 'Administrative', 'Care plans record each person''s needs and risks and are reviewed regularly.'),
  ('ad4f0ed2-7c58-5c4d-a24d-cc20840a618e', 'Medicines policy', 'Administrative', 'Medicines are handled under a written policy by trained, competent staff.'),
  ('d4ce64a5-5fa6-548d-9a90-881de27e5c87', 'Medication records', 'Administrative', 'Medication given is recorded at the time on a MAR chart; errors are reported.'),
  ('42bdd9fc-ede7-5b49-b763-13ee510e34dd', 'Medicines stored securely', 'Engineering', 'Medicines are stored securely at the right temperature, with controlled drugs double-locked.'),
  ('d61f2bdf-e0ed-5d78-b079-3f954d00fe92', 'Safeguarding procedures', 'Administrative', 'Staff are trained in safeguarding and know how to raise concerns.'),
  ('7bb2413c-a9f2-570a-96c9-67d05229eb6c', 'Recruitment checks', 'Administrative', 'Staff working with vulnerable people or children have appropriate DBS and reference checks.'),
  ('4198ff0b-daa2-5627-bb5b-1ec2878c5da6', 'Bed rails assessed', 'Administrative', 'Bed rails are used only after an individual assessment and checked for gaps and fit.'),
  ('70bd0638-4cba-5609-81a5-498eceeb0f20', 'Oxygen safety', 'Administrative', 'Oxygen is stored and used away from heat, flames and oils, with no-smoking signs.'),
  ('a2fde387-4948-5224-a185-ece0dc619311', 'Falls risk assessment', 'Administrative', 'Each person''s falls risk is assessed and aids, alarms and checks are provided.'),
  ('f243e608-4f42-5d0a-a7b1-60a8bc8d9b5a', 'Behaviour support plans', 'Administrative', 'Behaviour support plans describe triggers and calming approaches for each person.'),
  ('11a34df9-f502-5ea2-926f-01ed47fed075', 'Radiation protection adviser', 'Administrative', 'An RPA is appointed, local rules are written and controlled areas are defined.'),
  ('a51719bc-884a-59c2-bbaa-923f6aa4917e', 'X-ray equipment tested', 'Administrative', 'X-ray equipment is critically examined and quality-assured at set intervals.'),
  ('1e737ffd-ca48-5bbb-84f1-19447715b7f3', 'Laser local rules', 'Administrative', 'Lasers and IPL are used under local rules by trained operators, with the controlled area signed.'),
  ('9ab7d5cd-32af-590b-af5b-4c64b3f5f29e', 'Laser eyewear', 'PPE', 'Laser-specific eyewear is worn by operators and clients.'),
  ('10f37e64-09b5-5200-9562-243d79d57f33', 'Crowd management plan', 'Administrative', 'Capacity, stewarding, routes and communication are planned for the event.'),
  ('06211108-cf72-5648-812d-00bce5f72d92', 'Liaison with authorities', 'Administrative', 'Licensing, emergency services and the venue are consulted before the event.'),
  ('b366f30f-bbfc-5da6-ba0b-db6f3be03de5', 'Temporary structures checked', 'Administrative', 'Stages, marquees and inflatables are erected to the supplier''s instructions and checked before use.'),
  ('93e17a6e-3bfd-5d55-87fb-31355b5cac65', 'Inflatables tested and supervised', 'Administrative', 'Inflatables have a current PIPA or ADIPS tag, are anchored, and are supervised at all times.'),
  ('0fef91dc-0193-5a1f-bd75-b7d152014e9c', 'Wind speed limits', 'Administrative', 'Wind speeds are monitored and use stops above the manufacturer''s limit.'),
  ('805b8212-c820-5103-89af-ac043c954c7f', 'Gym inductions', 'Administrative', 'Members complete an induction and health questionnaire before using the gym.'),
  ('7629eafd-c8f9-59d7-844d-37a4a7c402db', 'Fitness equipment serviced', 'Administrative', 'Gym equipment is checked daily and serviced to the manufacturer''s schedule.'),
  ('d28d1dd2-e66e-5599-b3d8-d3d2052a50c9', 'Qualified instructors', 'Administrative', 'Classes and coaching are led by qualified instructors with first aid cover.'),
  ('2e6b12bf-2829-5374-80f8-244cc1ed0091', 'Sauna and steam room controls', 'Engineering', 'Saunas and steam rooms have timers, guarded heaters, alarms and regular checks.'),
  ('5a5b1b08-c30e-5b84-9502-704dde78ce19', 'Golfer warnings', 'Administrative', 'Staff working on the course watch play, wait for golfers and wear hi-vis.'),
  ('132a7d82-4fd4-5852-86d7-9d10f23ccf66', 'Tack checked', 'Administrative', 'Riding equipment is checked before every ride and riders wear approved hats.'),
  ('2cae4424-f9d3-53a9-b95f-3d5d012f26cf', 'Helmets', 'PPE', 'Approved helmets are worn for riding, cycling, quad bikes and similar activities.'),
  ('07f9aed9-a4a0-5099-8260-cea81aded996', 'Baler interlocks', 'Engineering', 'Balers and compactors have interlocked gates and are never entered while energised.'),
  ('4f17f80e-a5b2-56fb-a45f-fb5d02edc746', 'Conveyor guarding and stop wires', 'Engineering', 'Conveyors have guards at nip points and pull-wire stops along picking lines.'),
  ('c44d3094-b06b-5491-87cc-b8d45ef382cd', 'Waste segregated', 'Administrative', 'Waste is segregated and hazardous items removed before processing.'),
  ('a3c10f7e-014d-5a0d-ba99-d37dbda31bc7', 'Dust suppression', 'Engineering', 'Water sprays or misting systems suppress dust in yards and processing areas.'),
  ('c9957cc6-36ea-5daf-b402-4dcb5f5650ba', 'Safe battery charging', 'Engineering', 'Batteries are charged in a ventilated, fire-resistant area with approved chargers and not left charging overnight.'),
  ('3f7b312f-8cbf-5c4d-91de-07486bb467ed', 'High-voltage vehicle training', 'Administrative', 'Only trained technicians work on electric and hybrid vehicles, using insulated tools and isolation procedures.'),
  ('3c9cf7cf-6c67-5858-ae92-3420ff09b76b', 'Vehicle lifts examined', 'Administrative', 'Vehicle lifts are thoroughly examined every six months and vehicles supported on axle stands.'),
  ('00242d64-d2b4-518a-a5dd-c2f76501d5ae', 'Pit covers and barriers', 'Engineering', 'Inspection pits are covered or barriered when not in use.'),
  ('1cde8c94-b081-59ed-aa04-366a180045f9', 'Tyre inflation cage', 'Engineering', 'Split-rim and commercial tyres are inflated in a restraining cage with a remote gauge.'),
  ('722ca8de-53c9-50d4-bb7b-541a1892d5a8', 'Roadside working', 'Administrative', 'Roadside work uses warning lights, cones, hi-vis and a safe position away from traffic.'),
  ('a85e9cb7-aba3-5769-9c2e-81511057629d', 'Travel risk assessment', 'Administrative', 'Overseas travel is assessed for security, health and insurance, with an itinerary shared.'),
  ('8e53603a-59b8-57a3-a452-4e5432b0d92f', 'Health conditions supported', 'Administrative', 'Staff with health conditions are supported with individual plans and reasonable adjustments.'),
  ('0a8b1bd4-b639-505f-b061-2617aeadc751', 'Maintenance scope defined', 'Administrative', 'A written brief sets out which simple tasks staff may do and which must go to a contractor.'),
  ('e018f961-aafc-510c-95e3-48270ddef689', 'No gas, electrical or plumbing work', 'Elimination', 'In-house staff never work on gas, electrical or water systems; faults are reported to the helpdesk.'),
  ('9c2725a5-e7f5-5e7d-851f-6f07e6d86a06', 'No drilling into walls', 'Elimination', 'Staff do not drill into walls, floors or ceilings; existing fixings are used.'),
  ('4e1e5fdf-1205-54b8-a516-763a99f73736', 'Kitchen layout and ventilation', 'Engineering', 'The kitchen has enough space, non-slip flooring and canopy extraction over cooking equipment.'),
  ('33f0f518-d752-5dc3-8d90-aea38da7736a', 'Cellar access safe', 'Engineering', 'Cellar hatches have guard rails when open and stairs have handrails and good lighting.'),
  ('150d157a-333c-56df-9828-ea3bc544a7a5', 'CO2 monitoring in cellars', 'Engineering', 'Cellars with gas cylinders have CO2 and oxygen depletion alarms.'),
  ('f8ba48f2-4ef0-5728-b022-7623da5dcdb4', 'Beer line cleaning procedure', 'Administrative', 'Line cleaner is used to the supplier''s method, with lines flushed and taps labelled during cleaning.'),
  ('9fb16d32-1563-5dc7-9b00-d58f4d6d71ae', 'Glasswasher use', 'Administrative', 'Glasswashers are allowed to cool before unloading, and chemicals are fed by automatic dosing.'),
  ('149b137a-f547-5416-82d7-6925e7ddb205', 'Cleaning chemicals controlled', 'Administrative', 'Cleaning chemicals are diluted correctly, never mixed, and used with gloves and eye protection.'),
  ('19599418-cba8-544d-b0f3-4e0879dd55d8', 'Housekeeping trolleys', 'Substitution', 'Housekeeping trolleys are used and kept under weight limits; linen bags are not overfilled.'),
  ('bd5ead73-84bd-5b59-9b32-81aab684320d', 'Bed making technique', 'Administrative', 'Beds are made using good posture, working around the bed instead of overreaching.'),
  ('cf7d8ec7-1990-50e8-a3c3-dbaf06e9c20c', 'Laundry handled safely', 'Administrative', 'Soiled linen is bagged at source, washed at disinfection temperatures and kept apart from clean linen.'),
  ('25cfc31a-c044-5ba4-ac89-4987ec2e57f0', 'Spa pool operation', 'Administrative', 'Spa pools are disinfected, filtered and tested to HSE guidance, with bathing load and session times limited.'),
  ('1cf78e05-d2e8-5a0e-99ad-43ccb43b9ee3', 'Bath water temperature checked', 'Administrative', 'Bath and shower water is checked with a thermometer before the person gets in (no hotter than 44°C).'),
  ('252bc1e4-89c9-5f08-a02e-ffe8b0c46485', 'Dementia-friendly environment', 'Engineering', 'Signage, lighting, colour contrast and secure garden access help people with dementia move safely.'),
  ('23fada4d-3e6e-51ff-b4ca-6391863064f3', 'Seizure management plans', 'Administrative', 'People with epilepsy have a seizure management plan and staff are trained in emergency medication.'),
  ('9a751620-a553-5de4-8278-a84ecfe554ca', 'Changing units with steps', 'Engineering', 'Changing units have steps so children can climb up, avoiding lifting from the floor.'),
  ('e397ad72-2e75-5563-a7dd-a9059d19ddc0', 'Staffing ratios', 'Administrative', 'Staff-to-child or staff-to-client ratios meet the required levels at all times.'),
  ('6932f9ef-c491-5acb-9acc-1412e7f9bb89', 'Play equipment inspected', 'Administrative', 'Play equipment and surfaces are checked daily and inspected annually by a competent inspector.'),
  ('e2325e2d-e55a-517e-ab13-5b3fad51aa8b', 'Off-site visit plan', 'Administrative', 'Trips are planned and approved, with consent, ratios, first aid and emergency contacts in place.'),
  ('f9c4cc60-be15-5fb5-918d-16e26ca501f1', 'Science practicals controlled', 'Administrative', 'Practicals follow CLEAPSS guidance, are prepared by technicians and supervised by teachers.'),
  ('d3559901-3a04-5e2d-a440-aa1e404e4d2b', 'Kiln controls', 'Engineering', 'Kilns have interlocks or are in a locked area, with ventilation and warning signs while firing.'),
  ('9c3ebc5f-425f-5a22-956b-8a048ff827b7', 'Workshop rules for pupils', 'Administrative', 'Pupils use machines only after instruction, under supervision, with guards and eye protection.'),
  ('128c6890-134c-576a-bc5d-2b83d65783d1', 'Amalgam and mercury controlled', 'Administrative', 'Encapsulated amalgam is used, separators fitted, and spill kits available.'),
  ('60f4af5d-63b3-575f-82e0-bbc157b3b636', 'Instrument decontamination', 'Administrative', 'Instruments are decontaminated and sterilised following national guidance, with autoclave records.'),
  ('ccafb0f0-c125-5462-b68d-c25c218b6140', 'Cytotoxic drugs handled safely', 'Administrative', 'Cytotoxic drugs are prepared and disposed of using closed systems and specific PPE.'),
  ('40978380-e41d-555e-8b27-05b97521e22a', 'Anaesthetic gas scavenging', 'Engineering', 'Anaesthetic gases are scavenged and equipment leak-checked.'),
  ('aad17779-4bc2-5595-accc-4a6187cec926', 'Skin sensitivity tests', 'Administrative', 'Patch or skin sensitivity tests are done 48 hours before colour and certain treatments.'),
  ('e5faaccb-bd4f-5294-a449-a6b953b32a40', 'Client consultation', 'Administrative', 'A consultation and medical history check is completed before each treatment.'),
  ('9c1c3c1b-673a-554e-be66-f1bb67636fdb', 'Qualified practitioners', 'Administrative', 'Treatments are carried out only by suitably qualified and insured practitioners, with a prescriber where required.'),
  ('1ee40e5a-ca4f-5fc2-bda2-520a2c836e70', 'Solvent controls', 'Engineering', 'Dry cleaning machines are closed-loop, maintained, and solvent stored and disposed of safely.'),
  ('ba5b7aca-3573-55a9-b27d-4aeab062db78', 'Safe roof access', 'Engineering', 'Access to roofs is by a secured ladder or tower, with edge protection at the access point.'),
  ('01aaf493-53a6-51ca-ab32-73fb123e3e45', 'Scaffold tagged', 'Administrative', 'Scaffolds carry a tag showing the latest inspection and are not altered by anyone except scaffolders.'),
  ('11783cb4-7a9b-5650-a256-bf86a99e8a96', 'Disc cutters controlled', 'Administrative', 'Disc cutters are used by trained operators with the correct blade, guard and water suppression.'),
  ('2655648a-9023-5c46-bd97-153cc51936b9', 'Low-level platforms for decorating', 'Substitution', 'Hop-ups and podiums are used instead of chairs or trestles.'),
  ('f6cb5b63-f982-50f2-ab25-0d3a6395928f', 'Water and heating isolated', 'Administrative', 'Systems are isolated, drained and cooled before work, and soldering uses a heat mat.'),
  ('cf09f8a8-05cf-5d43-a1c7-31ebb4ae28c8', 'Glass lifting equipment', 'Substitution', 'Glass is moved with suction lifters and A-frames, and cut-resistant gloves and sleeves are worn.'),
  ('b5fa8a19-d8f5-52fb-9057-1a09125ac54f', 'Wood dust extraction', 'Engineering', 'Woodworking machines are connected to extraction that is examined every 14 months.'),
  ('9cda070d-f63a-5a71-83a9-212af585f17e', 'Braked machines', 'Engineering', 'Woodworking machines with run-down times over 10 seconds are fitted with brakes.'),
  ('06b7c406-8f3a-5d6b-8561-b25f5d4bd731', 'Welding screens and fume extraction', 'Engineering', 'Welding bays have screens and on-torch or local fume extraction.'),
  ('f219c3e4-b352-5428-ad23-51594654da81', 'Welding PPE', 'PPE', 'Welding helmets with the right filter, leather gloves and flame-resistant clothing are worn.'),
  ('badb7ddc-b26c-5a83-86a4-a1f282dca22c', 'Metalworking fluids managed', 'Administrative', 'Fluid concentration and bacteria are checked weekly, and machines have splash guards and mist extraction.'),
  ('8069990b-5f41-5458-bd95-e104ac889319', 'Shot blasting PPE', 'PPE', 'Blasters wear air-fed helmets and protective suits, and cabinets are kept sealed.'),
  ('4e869b8d-e4d0-5049-bb1c-338adc67d318', 'Mixer bowl guards', 'Engineering', 'Mixers have interlocked bowl guards; bowls are never reached into while moving.'),
  ('99e121ec-4570-5930-8dd1-eb1b6314e60e', 'Flour dust controlled', 'Engineering', 'Flour is added slowly, mixers start at low speed and dust is cleaned by vacuum, not brushing.'),
  ('da707cd6-33dc-5dd3-98f9-7dc8a9a91424', 'Tail lifts used safely', 'Administrative', 'Tail lifts are thoroughly examined every six months; loads are secured and operators stand clear of edges.'),
  ('3e6c2955-7a7f-55c4-ba8d-62528cb49e63', 'Coupling procedure', 'Administrative', 'Drivers follow a coupling procedure including tug test and parking brake checks.'),
  ('5d1b210f-d4cf-542d-ba54-6e8f28d5d37e', 'Cab access steps', 'Engineering', 'Drivers use steps and handholds facing the vehicle; no jumping from cabs or trailers.'),
  ('c34f4948-4fbf-5d89-b4f3-74eca31cf196', 'Roll-over protection', 'Engineering', 'Tractors have roll-over protection and seat belts are worn; quad bikes have helmets and training.'),
  ('46eff92c-340a-50be-bceb-835a2b089e94', 'PTO guards', 'Engineering', 'PTO shafts are fully guarded and machinery is switched off before clearing blockages.'),
  ('7031893f-4caa-54bd-9da7-a8134bd91d53', 'Safe stop', 'Administrative', 'Before leaving a vehicle or clearing machinery: handbrake on, controls neutral, engine off, key out.'),
  ('8fc9a497-b47d-5714-9549-edb36f17b3fd', 'No entry into grain bins', 'Elimination', 'Grain bins are not entered while emptying; entry needs a permit, harness and standby person.'),
  ('fb8a13a1-f816-544d-986b-1537838de56a', 'Shed ventilation', 'Engineering', 'Poultry sheds are ventilated and ammonia levels checked before work.'),
  ('6e57604c-66ee-5e4e-86ec-af5b277ffae1', 'Tree climbing teams', 'Administrative', 'Tree climbing needs a minimum of two trained people with an aerial rescue plan.'),
  ('d1d51119-d0f5-561e-b8b3-432124ce799b', 'Chipper safety', 'Engineering', 'Chippers are fed from the side, with feed controls tested and nobody reaching into the chute.'),
  ('5b74a293-5e6d-5ee5-a157-e9a71a7d9fdc', 'Golf buggy rules', 'Administrative', 'Buggies are driven only on approved paths by authorised drivers, with passenger limits.'),
  ('a0af82c7-adf0-5ba7-bb50-67bbcad98716', 'Quad and Segway training', 'Administrative', 'Riders receive training and a safety briefing and stay within marked routes.'),
  ('e9d92bd4-4e21-5531-9470-47673ee6d5ae', 'Stable and yard layout', 'Engineering', 'Stables have wide doors, secure fittings and non-slip yards.'),
  ('6f700aca-9df1-5a00-a2e1-add2ff002c2d', 'Accessible routes', 'Engineering', 'Routes, ramps and facilities are accessible to people with disabilities.'),
  ('55000a76-0437-5bfe-9bc4-8a1e78895e31', 'Cashing-up procedure', 'Administrative', 'Cash is counted out of public view, in a secure room, with two people where possible.'),
  ('aca2d599-a7ae-5cac-9f83-951f86e2b2cd', 'Mezzanine edge protection', 'Engineering', 'Mezzanine floors have guard rails, signed load limits and gated loading points.'),
  ('ce23748c-42b1-5395-b023-26f33fe49673', 'Hot drinks equipment', 'Administrative', 'Coffee machines are maintained, steam wands purged away from the body and descaled to schedule.'),
  ('59a370de-9fa8-58a7-b030-26f1706b4123', 'Mechanical sheeting', 'Engineering', 'Skips and RoRo containers are sheeted with mechanical systems or from a sheeting gantry.'),
  ('5a033f10-2ad8-5234-b8cd-49f60722ed15', 'Shear controls and guarding', 'Engineering', 'Shears have guards, two-hand or remote controls and are fed with handling equipment.'),
  ('7c4711de-f401-5920-8d8b-f633b24a84e0', 'Hazardous waste procedure', 'Administrative', 'Hazardous items found in waste are isolated, labelled and stored for specialist disposal.'),
  ('0e17cf45-531a-5e41-b98a-e217f9289812', 'Pre-travel briefing', 'Administrative', 'Travellers are briefed on local risks, vaccinations and emergency contacts before departure.'),
  ('54465f03-20ad-5c6c-921f-25b0748bcfa3', 'Event planning and alcohol', 'Administrative', 'Social events are planned with safe transport home, sensible alcohol provision and a responsible host.'),
  ('e06b2778-d78b-501a-a3dd-58db44debefb', 'Safety signs at water', 'Engineering', 'No-diving and depth signs, and life-saving equipment, are provided at the water''s edge.'),
  ('68c884e4-5a7a-5c0d-9056-97d8d2f8c5d8', 'Powered gate safety devices', 'Engineering', 'Powered gates have safety edges, photocells and force limits, tested at each service.'),
  ('222e16e6-5bf3-5824-ad01-691b4c20402a', 'Crane and lifting gear examined', 'Administrative', 'Overhead cranes and lifting accessories are thoroughly examined and operators trained.'),
  ('513ad9a2-8ad7-5f8c-8a56-2b5ec95023f5', 'Mechanical post drivers', 'Substitution', 'Post drivers and augers are used with guards and hearing protection instead of manual rammers where possible.'),
  ('57f3f1ab-74c0-554d-9160-6ff7a4926a8a', 'Cleaning machines used safely', 'Administrative', 'Cleaning machines are checked, cables managed, and wet areas signed until dry.'),
  ('53ed5d89-37db-55d8-9916-f733c5ee8f11', 'Fogging procedure', 'Administrative', 'Rooms are cleared and sealed, smoke detectors isolated, and re-entry delayed until the product has settled.'),
  ('13be9c96-a3b5-59fc-8d63-0ba093e0bd81', 'Exhibition build plan', 'Administrative', 'Stand building follows the organiser''s rules, with materials fire-rated and work at height planned.'),
  ('3f5a449e-23e6-5334-885e-ad34d6f7797b', 'Car park duties', 'Administrative', 'Car park staff wear hi-vis, stand in safe positions and use agreed hand signals.'),
  ('2e2e602b-8422-5105-a093-8b909b332939', 'Agency and host liaison', 'Administrative', 'The host provides a site induction and the agency confirms the worker is trained for the role.'),
  ('b64faeab-5047-553c-a7d7-ea20b3275055', 'Home workers kept in contact', 'Administrative', 'Home workers have regular contact with their manager and a way to report problems.')
insert into public.hazard_register (id, category, title, description) values
  ('391a16b1-e3ed-5bb1-a9a8-1a68ba7e35c3', 'Slips, trips and falls', 'Slips, trips and falls on the same level', 'Wet or uneven floors, spills, trailing cables, clutter and poor lighting can cause people to slip or trip, leading to sprains, fractures or head injuries.'),
  ('2c9d3f1b-2033-50d5-b637-a2d6e4b9033c', 'Slips, trips and falls', 'Falls on stairs and steps', 'Stairs, steps and changes in level can cause falls, especially when carrying items or in poor light.'),
  ('6e275d19-1745-5681-b084-f726b00c78d2', 'Slips, trips and falls', 'Ice and snow', 'Icy or snowy paths, car parks and entrances can cause serious falls.'),
  ('017450b3-fab9-550e-8674-0c3f3e6ff8b3', 'Working at height', 'Falls from ladders and stepladders', 'Overreaching, defective ladders or poor footing can cause falls from ladders, with serious injuries.'),
  ('3215f3dd-bda9-5639-9636-ebd3cad8165d', 'Working at height', 'Falls from height', 'Work on roofs, platforms, edges or openings can lead to falls causing major or fatal injury.'),
  ('53caf44a-673b-5657-b7b7-6031e3990378', 'Working at height', 'Mobile towers', 'Incorrectly built or moved towers can collapse or overturn, and users can fall.'),
  ('024bfd45-4e00-5dd9-8df9-d0cdbaf15938', 'Working at height', 'Mobile elevating work platforms', 'MEWPs can overturn, trap operators against structures or eject them.'),
  ('f925bdf3-50f3-537d-8f63-3526b7e3d14d', 'Working at height', 'Falling objects', 'Tools, materials or stored goods falling from height can strike people below.'),
  ('0b5324d0-8c87-5f13-b6cc-0c92a81650aa', 'Manual handling', 'Manual handling of loads', 'Lifting, carrying, pushing and pulling heavy, bulky or awkward loads can cause back and musculoskeletal injuries.'),
  ('a551c8fd-1b66-5bfe-88f9-d8b4cd7f0bea', 'Manual handling', 'Repetitive movements and posture', 'Repetitive tasks and awkward postures can cause upper limb disorders and back pain.'),
  ('a786e417-589f-52ea-af1a-d203f52ed0d0', 'Manual handling', 'Moving and handling people', 'Helping people move, transfer or reposition can injure carers and the person being moved.'),
  ('5fc8d80a-bbd8-586e-98c7-f0d554d4e516', 'Electrical', 'Electric shock and burns', 'Faulty equipment, damaged leads or unsafe work on electrical systems can cause shock, burns, fire or death.'),
  ('9a76e4ce-cdfc-5c81-a186-6a132eb9eddc', 'Electrical', 'Striking buried or hidden services', 'Digging or drilling can strike buried cables, gas pipes or hidden wiring.'),
  ('c7e328f8-dde9-51ce-b2cc-60b5af72b209', 'Electrical', 'Overhead power lines', 'Tall vehicles, plant, ladders or tipping trailers can contact overhead lines.'),
  ('6ead5292-c689-5307-a5ea-d3dca4952708', 'Fire', 'Fire', 'A fire could cause burns, smoke inhalation or death and destroy the premises.'),
  ('1b741e69-2a2b-5380-bedf-463908c85811', 'Fire', 'Hot work', 'Welding, cutting, torches and grinding can start fires in nearby materials.'),
  ('32a66ace-8285-5551-a2bd-a9bdb3e9c3ac', 'Fire', 'Flammable liquids and gases', 'Flammable liquids, vapours and gases can ignite or explode.'),
  ('830168c0-14b2-5db3-961b-1544f32f2598', 'Hazardous substances (COSHH)', 'Hazardous substances', 'Contact with or breathing in chemicals can cause burns, dermatitis, respiratory illness or poisoning.'),
  ('c0692318-5348-5e10-be88-b90deb16a441', 'Hazardous substances (COSHH)', 'Dermatitis and skin damage', 'Wet work and contact with chemicals or products can cause contact dermatitis.'),
  ('e3cc927f-3434-5a8b-88cb-3de572628bc0', 'Hazardous substances (COSHH)', 'Dust and fume', 'Breathing dust or fume, such as wood dust, silica or welding fume, can cause serious lung disease and cancer.'),
  ('e3cd2e44-0d49-5f52-b77e-60dd513dae05', 'Hazardous substances (COSHH)', 'Silica dust', 'Cutting or grinding stone, brick and concrete releases silica that causes silicosis and lung cancer.'),
  ('003a7066-8fb4-5add-a9e0-6b7690438723', 'Asbestos', 'Disturbance of asbestos', 'Drilling, cutting or damaging asbestos-containing materials can release fibres that cause fatal lung disease decades later.'),
  ('ba78229b-eb5b-5177-91be-e810ca09dc45', 'Water and flooding', 'Legionella bacteria', 'Water systems that are poorly maintained can grow legionella, which causes Legionnaires'' disease when spray is breathed in.'),
  ('e5d77392-11a7-5d6c-b830-85cef3a5efab', 'Fire', 'Burns and scalds', 'Hot water, surfaces, liquids, steam and equipment can cause burns and scalds.'),
  ('1de59919-8018-5d50-a3b0-61d667ac4a76', 'Noise and vibration', 'Noise', 'Exposure to loud noise can cause permanent hearing loss and tinnitus.'),
  ('187d9cd0-0be0-5843-b458-976e83c7ca16', 'Noise and vibration', 'Hand-arm vibration', 'Regular use of vibrating tools can cause hand-arm vibration syndrome and carpal tunnel syndrome.'),
  ('a58877b2-6ac5-5cb3-96e2-4b741f38bfc1', 'Machinery and equipment', 'Contact with moving parts of machinery', 'Entanglement, cuts, crushing or amputation from moving parts, blades or cutters.'),
  ('360ef45b-08e9-543a-863b-a116de2a8e13', 'Machinery and equipment', 'Cutting machinery and blades', 'Saws, cutters and slicers can cause serious cuts and amputations.'),
  ('4aafb60a-06b0-529a-8c19-83a2a878b653', 'Machinery and equipment', 'Hand tools and power tools', 'Defective or misused tools can cause cuts, eye injuries and impact injuries.'),
  ('88938df8-ee7d-5280-a1ca-f20f2b08cb72', 'Machinery and equipment', 'Flying particles and debris', 'Grinding, cutting, mowing and striking can throw particles into eyes or at bystanders.'),
  ('6a13ad16-b24b-5f72-9ccd-213689b3ac2d', 'Machinery and equipment', 'Pressure systems and compressed air', 'Failure of pressure vessels, hoses or fittings can cause explosion or injection injuries.'),
  ('7ea3717e-086e-59e4-96e7-78f0aa9b5fe2', 'Gas', 'Gas cylinders', 'Damaged or poorly stored cylinders can leak, fall, catch fire or explode.'),
  ('874874be-fcf0-5e30-b033-08e90f1de94e', 'Gas', 'Gas appliances and carbon monoxide', 'Faulty gas appliances or flues can leak gas or produce carbon monoxide.'),
  ('6eb3f224-616a-56e1-ad0d-cab46a81ed06', 'Vehicles and traffic', 'Workplace transport', 'People can be struck or crushed by moving vehicles, plant or lift trucks.'),
  ('4c869f16-1b8e-5e1f-9023-896cc3d8700a', 'Vehicles and traffic', 'Lift trucks', 'Lift trucks can overturn, drop loads or strike pedestrians.'),
  ('c2179df3-ca68-5d41-95f6-a4f9e6c86c7c', 'Vehicles and traffic', 'Driving for work', 'Road traffic collisions caused by fatigue, distraction, vehicle faults or weather.'),
  ('e2a53c91-4318-55b9-8d50-192e35027495', 'Vehicles and traffic', 'Loading and unloading vehicles', 'Falls from vehicles, moving loads, and vehicles moving during loading.'),
  ('754269ca-2810-5665-9938-9d0013a0d577', 'Vehicles and traffic', 'Mobile plant', 'Excavators, dumpers and similar plant can overturn or strike people.'),
  ('bbadac6a-02cc-5f94-8391-4c97322dff02', 'Lone working', 'Working alone', 'Someone working alone may not get help quickly after an accident, illness or attack.'),
  ('1e3a08e9-ae3f-551d-ba5b-2cff56adb361', 'Violence and aggression', 'Violence and aggression', 'Staff may face verbal abuse, threats or physical assault from members of the public or service users.'),
  ('62933a45-6fde-5c14-8f1b-5c0175f44f9b', 'Stress and wellbeing', 'Work-related stress', 'Excessive demands, lack of control or poor support can cause anxiety, depression and absence.'),
  ('70ccd2e1-e685-5db8-afc4-5f32df4f04e3', 'Stress and wellbeing', 'Display screen equipment', 'Prolonged computer use with a poor set-up can cause neck, back and upper limb pain and eye strain.'),
  ('3d7587ba-ae0a-58a0-827d-ec67f1630c50', 'Health', 'Infection', 'Infections can spread between staff and others through contact, body fluids or contaminated surfaces.'),
  ('549e6fa9-81cc-5b03-bc79-4e8393cbe534', 'Health', 'Sharps and needlestick injuries', 'Needles, blades and other sharps can cause injuries and transmit blood-borne viruses.'),
  ('63af5476-d19d-5ded-9e54-db11fdc24c41', 'Health', 'Biological agents and body fluids', 'Blood, body fluids, animal waste and contaminated materials can transmit infection.'),
  ('b0311a09-ca08-52ca-bf3f-88a47f7d5d3a', 'Food safety', 'Food poisoning', 'Poor hygiene, cross-contamination or temperature control can cause food poisoning.'),
  ('a6eccc8d-6335-5a7b-8b83-7193845828d0', 'Food safety', 'Food allergens', 'Incorrect allergen information or cross-contamination can cause severe allergic reactions.'),
  ('0bb069f9-e0bc-5e3b-a62c-3ca35b78cb9f', 'Food safety', 'Knives and sharp utensils', 'Knives, slicers and broken glass can cause serious cuts.'),
  ('d2c161b9-16f5-5bab-a28e-b76a635288e2', 'Slips, trips and falls', 'Glass and glazing', 'Broken glassware or walking into glazing can cause cuts.'),
  ('6ef7cd6d-2583-58a1-851a-1ec328182f69', 'Confined spaces', 'Confined spaces', 'Lack of oxygen, toxic gases, flooding or engulfment in tanks, pits, silos or sewers can kill quickly.'),
  ('6836a0d7-1c80-5fb8-9aac-e70f9efed5f9', 'Water and flooding', 'Drowning', 'Falling into pools, rivers, lakes or tanks can lead to drowning.'),
  ('99c012b6-9005-5c8e-b014-6f4880c01d80', 'Hazardous substances (COSHH)', 'Pool and spa chemicals', 'Mixing or mishandling pool chemicals can release toxic chlorine gas.'),
  ('14a5fdd1-ba60-531c-bb47-40eebb387859', 'Animals', 'Animal handling', 'Animals can kick, bite, crush or scratch people, or pass on diseases.'),
  ('2ed69c4f-ffd4-5f0a-bffd-46f83c8f3c6b', 'Working outdoors', 'Weather and sun exposure', 'Working outdoors can cause sunburn, skin cancer, heat stress, cold stress or lightning strike.'),
  ('a78b1b23-aa7c-59d2-bfcd-cf592ba7eba1', 'Working outdoors', 'Leptospirosis (Weil''s disease)', 'Water or soil contaminated by rat urine can cause leptospirosis through cuts or the mouth.'),
  ('b35ff4f0-04d7-5706-b0e6-7b9a0558e2ca', 'Hazardous substances (COSHH)', 'Pesticides and fertilisers', 'Pesticides and fertilisers can poison, burn or sensitise users and others nearby.'),
  ('8ff5a973-7532-528b-ba70-ae5f28a40785', 'Construction', 'Excavations', 'Excavations can collapse, flood or have people, vehicles or materials fall into them.'),
  ('b6660094-6867-592f-aafa-4e362b1f6a05', 'Construction', 'Collapse of structures', 'Temporary works, scaffolds, racking or marquees can collapse if poorly built or overloaded.'),
  ('aa47e22a-5a81-5134-8cb9-ff4a2ec72786', 'Public and visitors', 'Members of the public and visitors', 'Visitors and the public, including children, can be hurt by work activities or enter unsafe areas.'),
  ('a7b715b7-9d48-55b9-b1ec-9b123e981254', 'Public and visitors', 'Contractors on site', 'Contractors may not know site hazards, and their work can put staff and visitors at risk.'),
  ('ba8e0d5f-e55d-59a3-8c50-45b759de7054', 'Vulnerable people', 'Vulnerable workers', 'Young workers, new and expectant mothers and people with health conditions can be at greater risk.'),
  ('51b9e195-e896-5e5d-a721-40e9d92f652e', 'Vulnerable people', 'Safeguarding vulnerable people', 'Children and vulnerable adults could be harmed, abused or go missing.'),
  ('ef427f3c-bfb4-58e6-b7e7-24a9a33cda69', 'Health', 'Medicines', 'Medication errors, misuse or poor storage can harm patients and staff.'),
  ('259ee26e-8dd7-547f-9e07-50f0f0b6ddf6', 'Vulnerable people', 'Falls by residents or service users', 'Older or frail people may fall, with fractures and head injuries.'),
  ('cc43015a-6b7b-5891-b1e6-d3e745ac63fe', 'Radiation', 'Ionising radiation', 'X-ray equipment can expose staff and patients to radiation.'),
  ('087fbda8-144c-5390-b7da-be151bf8dcc6', 'Radiation', 'Lasers and intense light', 'Lasers and IPL can cause eye injury and skin burns.'),
  ('f7f9f455-42d8-5cc0-a627-546be966f331', 'Fire', 'Oxygen and medical gases', 'Oxygen enrichment greatly increases fire risk; cylinders can fall or leak.'),
  ('3dc87c11-4045-52ce-8ab7-804e7e5878e0', 'Events', 'Crowds and events', 'Overcrowding, poor routes or emergencies at events can lead to crush injuries.'),
  ('b25c2f13-a349-5d08-a0db-a66208b2c275', 'Fire', 'Lithium batteries', 'Damaged or overcharged lithium batteries can catch fire or explode.'),
  ('9a63135f-39ac-50ea-a1f2-ac5074d18a9c', 'Fire', 'Emergencies and first aid', 'Without arrangements, injuries and emergencies may not be dealt with quickly.')
