  ('dcc5643b-7930-5474-a071-2ebe8dcc4eb4', 'General', 'In house maintenance', 'Simple, low-risk maintenance tasks that staff can complete safely with hand tools, so contractors are only called for work beyond in-house competence.', array['Colleagues','Contractors','Visitors / guests','Members of the public']::text[], 4, 5, 2, 3),
