  ('0a8be349-9e1a-59da-9183-d27f48da2b5f', 'General', 'Use of ladders and stepladders', 'Short-duration, light work from ladders and stepladders, where a safer platform is not justified.', array['Colleagues','Contractors']::text[], 3, 4, 2, 3),
