-- Safetybiz starter library: hazard register, control register and topic library.
-- Written for Safetybiz. Run once after schema.sql. Safe to re-run (updates existing rows).
begin;
on conflict (id) do update set title = excluded.title, type = excluded.type, description = excluded.description;
on conflict (id) do update set category = excluded.category, title = excluded.title, description = excluded.description;
on conflict do nothing;
on conflict (id) do update set sector = excluded.sector, title = excluded.title, description = excluded.description, people_exposed = excluded.people_exposed, init_l = excluded.init_l, init_s = excluded.init_s, res_l = excluded.res_l, res_s = excluded.res_s;
on conflict do nothing;
on conflict do nothing;
commit;
